<script setup>
import {onMounted,reactive,ref,watch} from "vue";import ConfirmDialog from "./ConfirmDialog.vue";import{authFetch,ensureUnlocked}from"../utils/auth.js";import{FOOD_CATEGORY_FILTERS,foodCategoryLabels}from"../utils/foodCategories.js";
const foods=ref([]),category=ref(""),editingId=ref(null),manageMode=ref(false),foodToDelete=ref(null),deletingFood=ref(false),saving=ref(false),error=ref("");const blank=()=>({name:"",base_amount:100,unit:"g",protein:"",fat:"",carbs:"",has_alcohol:false,alcohol_abv:0,nutrition_source:"manual",estimated:false});const form=reactive(blank());
async function request(url,options){const response=await authFetch(url,options);if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(Array.isArray(body.detail)?body.detail[0]?.msg:body.detail||"请求失败")}return response.status===204?null:response.json()}
async function loadFoods(){error.value="";const params=new URLSearchParams({limit:"100"});if(category.value)params.set("category",category.value);try{foods.value=await request(`/api/foods?${params}`)}catch(reason){error.value=reason.message}}function reset(){editingId.value=null;Object.assign(form,blank())}function edit(food){editingId.value=food.id;Object.assign(form,{name:food.name,base_amount:food.base_amount,unit:food.unit,protein:food.protein,fat:food.fat,carbs:food.carbs,has_alcohol:Number(food.alcohol_abv)>0,alcohol_abv:food.alcohol_abv||0,nutrition_source:food.nutrition_source,estimated:food.estimated})}
async function save(){saving.value=true;error.value="";try{await request(editingId.value?`/api/foods/${editingId.value}`:"/api/foods",{method:editingId.value?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,base_amount:Number(form.base_amount),protein:Number(form.protein||0),fat:Number(form.fat||0),carbs:Number(form.carbs||0),alcohol_abv:form.has_alcohol?Number(form.alcohol_abv||0):0})});reset();await loadFoods()}catch(reason){error.value=reason.message}finally{saving.value=false}}function remove(food){foodToDelete.value=food}async function confirmRemove(){if(!foodToDelete.value||deletingFood.value)return;deletingFood.value=true;error.value="";try{const food=foodToDelete.value;await request(`/api/foods/${food.id}`,{method:"DELETE"});foods.value=foods.value.filter(item=>item.id!==food.id);if(editingId.value===food.id)reset();foodToDelete.value=null}catch(reason){error.value=`删除失败：${reason.message}`}finally{deletingFood.value=false}}async function selectCategory(value){category.value=value;await loadFoods()}watch(()=>form.has_alcohol,enabled=>{if(enabled)form.unit="ml";else form.alcohol_abv=0});onMounted(loadFoods);
async function toggleManage(){if(manageMode.value){manageMode.value=false;return}try{await ensureUnlocked();manageMode.value=true}catch{}}
</script>
<template><section class="card food-library library-view" :class="{managing:manageMode}"><div class="section-heading"><div><p class="section-kicker">FOOD LIBRARY</p><h2>食物库</h2></div><div class="library-heading-actions"><button v-if="editingId" class="text-button" @click="reset">取消编辑</button><button class="text-button manage-button" @click="toggleManage">{{manageMode?'完成':'管理'}}</button></div></div><form class="food-form" novalidate @submit.prevent="save"><label>名称<input v-model.trim="form.name" required/></label><label>基准数量<input v-model="form.base_amount" required type="number" min="0" step="1"/></label><label>单位<select v-model="form.unit"><option>g</option><option>ml</option><option>个</option><option>份</option></select></label><label>碳水<input v-model="form.carbs" type="number" min="0" step="1"/></label><label>蛋白质<input v-model="form.protein" type="number" min="0" step="1"/></label><label>脂肪<input v-model="form.fat" type="number" min="0" step="1"/></label><label class="checkbox alcohol-toggle"><input v-model="form.has_alcohol" type="checkbox"/>含酒精</label><label v-if="form.has_alcohol">酒精度 %<input v-model="form.alcohol_abv" type="number" min="0" max="100" step="1"/></label><button class="primary" :disabled="saving">{{editingId?'保存食物':'加入食物库'}}</button></form><div class="category-filter library-filter"><button v-for="item in FOOD_CATEGORY_FILTERS" :key="item||'all'" type="button" :class="{active:category===item}" @click="selectCategory(item)">{{item||'全部'}}</button></div><p v-if="error" class="error">{{error}}</p><div v-if="foods.length" class="food-list"><article v-for="food in foods" :key="food.id" tabindex="0" @click="edit(food)" @keydown.enter="edit(food)"><div><strong>{{food.name}} <i v-if="food.estimated" class="source-tag ai_estimated">估算</i></strong><span>{{food.base_amount}}{{food.unit}} · {{food.calories}} kcal · C {{food.carbs}} / P {{food.protein}} / F {{food.fat}} <template v-if="food.alcohol_abv>0"> · {{food.alcohol_abv}}% vol</template> · {{foodCategoryLabels(food).join(' / ')}}</span></div><div class="actions"><button class="edit" @click.stop="edit(food)">编辑</button><button class="delete" @click.stop="remove(food)">删除</button></div></article></div><p v-else-if="!error" class="empty compact">当前分类没有食物。</p><ConfirmDialog :open="Boolean(foodToDelete)" :item-name="foodToDelete?.name||''" :loading="deletingFood" @cancel="foodToDelete=null" @confirm="confirmRemove"/></section></template>
